async function toggleCpanelEmailPermissions(config, emailAddress, permissions, domainOverride) {
  const cleanEmail = emailAddress.trim().toLowerCase();
  const parts = cleanEmail.split("@");
  const emailUser = parts[0];
  const emailDomain = (domainOverride || parts[1] || config.domain || "").trim().toLowerCase();
  const fullEmail = emailDomain ? `${emailUser}@${emailDomain}` : cleanEmail;
  const results = {};
  const errors = [];
  const callPermissionUapi = async (funcName) => {
    try {
      return await callCpanelUapi(config, "Email", funcName, { email: fullEmail });
    } catch (e1) {
      try {
        return await callCpanelUapi(config, "Email", funcName, { email: emailUser, domain: emailDomain });
      } catch (e2) {
        throw new Error(e1.message || e2.message);
      }
    }
  };
  if (permissions.allowSend !== void 0) {
    const uapiFunc = permissions.allowSend ? "unsuspend_outgoing" : "suspend_outgoing";
    try {
      results.outgoing = await callPermissionUapi(uapiFunc);
    } catch (e) {
      console.error(`[cPanel] ${uapiFunc} failed for ${fullEmail}:`, e.message);
      results.outgoing = { error: e.message };
      errors.push(`Kirim: ${e.message}`);
    }
  }
  if (permissions.allowReceive !== void 0) {
    const uapiFunc = permissions.allowReceive ? "unsuspend_incoming" : "suspend_incoming";
    try {
      results.incoming = await callPermissionUapi(uapiFunc);
    } catch (e) {
      console.error(`[cPanel] ${uapiFunc} failed for ${fullEmail}:`, e.message);
      results.incoming = { error: e.message };
      errors.push(`Terima: ${e.message}`);
    }
  }
  if (permissions.allowLogin !== void 0) {
    const uapiFunc = permissions.allowLogin ? "unsuspend_login" : "suspend_login";
    try {
      results.login = await callPermissionUapi(uapiFunc);
    } catch (e) {
      console.error(`[cPanel] ${uapiFunc} failed for ${fullEmail}:`, e.message);
      results.login = { error: e.message };
      errors.push(`Login: ${e.message}`);
    }
  }
  if (errors.length > 0 && Object.keys(results).length === errors.length) {
    throw new Error(errors.join(", "));
  }
  return {
    ok: true,
    message: `Izin akun email ${fullEmail} berhasil diperbarui.`,
    results
  };
}

