async function ensureColumn(p, table, column, definition) {
  try {
    const [rows] = await p.query(`SHOW COLUMNS FROM \`${table}\` LIKE ?`, [column]);
    if (rows.length === 0) {
      console.log(`[DB Auto-Sync] Adding missing column \`${column}\` to table \`${table}\`...`);
      await p.query(`ALTER TABLE \`${table}\` ADD COLUMN \`${column}\` ${definition}`);
      console.log(`[DB Auto-Sync] Column \`${column}\` successfully added to \`${table}\`.`);
    }
  } catch (err) {
    console.error(`[DB Auto-Sync] Error ensuring column \`${column}\` in \`${table}\`:`, err.message);
  }
}
async function ensureDropTable(p, table) {
  try {
    const [rows] = await p.query(`SHOW TABLES LIKE ?`, [table]);
    if (rows.length > 0) {
      console.log(`[DB Auto-Clean] Dropping obsolete table \`${table}\`...`);
      try {
        await p.query(`SET FOREIGN_KEY_CHECKS = 0`);
        await p.query(`DROP TABLE IF EXISTS \`${table}\``);
        await p.query(`SET FOREIGN_KEY_CHECKS = 1`);
        console.log(`[DB Auto-Clean] Obsolete table \`${table}\` successfully dropped.`);
      } catch (err) {
        console.warn(`[DB Auto-Clean] Could not drop table \`${table}\`:`, err.message);
      }
    }
  } catch (err) {
    console.warn(`[DB Auto-Clean] Notice on dropping table \`${table}\`:`, err.message);
  }
}
