app.post("/api/bantuan/jenis", authenticate, async (req, res) => {
  try {
    await ensureLaporanBantuanSchema();
    const { nama_bantuan, istilah, kategori, metode_penyaluran, default_bank, default_nominal, default_items } = req.body;
    if (!nama_bantuan || !istilah) {
      return res.status(400).json({ error: "Nama bantuan dan istilah harus diisi" });
    }
    const cleanKategori = kategori === "barang" ? "barang" : "uang";
    const cleanMetode = metode_penyaluran === "tunai" ? "tunai" : "transfer";
    const cleanNominal = default_nominal ? parseFloat(String(default_nominal).replace(/[^0-9.]/g, "")) : null;
    const cleanItems = default_items ? typeof default_items === "object" ? JSON.stringify(default_items) : String(default_items) : null;
    await getPool().query(
      `INSERT INTO jenis_bantuan (nama_bantuan, istilah, kategori, metode_penyaluran, default_bank, default_nominal, default_items) 
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE 
                nama_bantuan = VALUES(nama_bantuan),
                kategori = VALUES(kategori),
                metode_penyaluran = VALUES(metode_penyaluran),
                default_bank = VALUES(default_bank),
                default_nominal = VALUES(default_nominal),
                default_items = VALUES(default_items)`,
      [nama_bantuan, istilah, cleanKategori, cleanMetode, default_bank || "BRI", cleanNominal, cleanItems]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
