app.get("/api/bantuan/penerima", authenticate, async (req, res) => {
  try {
    await ensureLaporanBantuanSchema();
    let whereClause = "";
    const params = [];
    if (req.user.type === "staff") {
      const perms = req.user.permissions || [];
      if (!perms.includes("all")) {
        const [rombelRows] = await getPool().execute("SELECT nama as name FROM rombongan_belajar WHERE wali_kelas_id = ? OR ptk_id = ?", [req.user.staff_id, req.user.staff_id]);
        if (rombelRows.length > 0) {
          const names = rombelRows.map((r) => r.name).filter(Boolean);
          if (names.length > 0) {
            whereClause = `WHERE rombel_data.rombel IN (${names.map(() => "?").join(",")})`;
            params.push(...names);
          } else {
            whereClause = `WHERE 1=0`;
          }
        } else {
          whereClause = `WHERE 1=0`;
        }
      }
    }
    const [rows] = await getPool().execute(`
            SELECT 
                pb.id as penerima_bantuan_id, s.peserta_didik_id as siswa_id, s.nisn, rombel_data.rombel, s.nik,
                jb.nama_bantuan, jb.istilah, pb.tahun, pb.semester, pb.tahap,
                pb.nominal as pb_nominal, pb.bank_rekomendasi, pb.items_barang,
                jb.kategori as kategori_bantuan, jb.metode_penyaluran, jb.default_nominal, jb.default_bank, jb.default_items,
                IFNULL(NULLIF(prb.nama_lengkap, ''), s.nama) as nama_lengkap,
                IFNULL(NULLIF(prb.tempat_lahir, ''), s.tempat_lahir) as tempat_lahir,
                IFNULL(prb.tanggal_lahir, s.tanggal_lahir) as tanggal_lahir,
                IFNULL(NULLIF(prb.nomor_hp, ''), s.nomor_telepon_seluler) as nomor_hp,
                IFNULL(NULLIF(prb.nomor_kk, ''), COALESCE(s.nomor_kk, s.no_kk, '')) as nomor_kk,
                IFNULL(NULLIF(prb.nama_ibu, ''), s.nama_ibu_kandung) as nama_ibu,
                IFNULL(NULLIF(prb.nik_ibu, ''), s.nik_ibu) as nik_ibu,
                IFNULL(NULLIF(prb.nama_ayah, ''), s.nama_ayah) as nama_ayah,
                IFNULL(NULLIF(prb.nik_ayah, ''), s.nik_ayah) as nik_ayah,
                IFNULL(NULLIF(prb.wali, ''), s.nama_wali) as nama_wali,
                IFNULL(NULLIF(prb.nik_wali, ''), s.nik_wali) as nik_wali,
                IFNULL(NULLIF(prb.alamat_jalan, ''), s.alamat_jalan) as alamat_jalan,
                IFNULL(NULLIF(prb.rt, ''), s.rt) as rt,
                IFNULL(NULLIF(prb.rw, ''), s.rw) as rw,
                IFNULL(NULLIF(prb.kelurahan, ''), COALESCE(s.desa_kelurahan, s.kelurahan, '')) as kelurahan,
                IFNULL(NULLIF(prb.kecamatan, ''), s.kecamatan) as kecamatan,
                IFNULL(NULLIF(prb.kota, ''), COALESCE(s.kabupaten_kota, s.kota, '')) as kota,
                IFNULL(NULLIF(prb.provinsi, ''), s.provinsi) as provinsi,
                db.bank, db.nomor_rekening, db.an_rekening, prb.penanggung_jawab_rekening
            FROM penerima_bantuan pb
            JOIN peserta_didik s ON s.peserta_didik_id = pb.siswa_id
            LEFT JOIN (
                SELECT ar.peserta_didik_id, MAX(rb.nama) as rombel
                FROM anggota_rombel ar
                JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
                WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
                GROUP BY ar.peserta_didik_id
            ) rombel_data ON rombel_data.peserta_didik_id = s.peserta_didik_id
            JOIN jenis_bantuan jb ON pb.istilah = jb.istilah
            LEFT JOIN (
                SELECT db1.*
                FROM data_bank db1
                INNER JOIN (
                    SELECT MAX(id) as max_id
                    FROM data_bank
                    GROUP BY siswa_id, istilah
                ) db2 ON db1.id = db2.max_id
            ) db ON db.siswa_id = s.peserta_didik_id AND db.istilah = pb.istilah
            LEFT JOIN (
                SELECT prb1.*
                FROM pengajuan_rekening_bantuan prb1
                INNER JOIN (
                    SELECT MAX(id) as max_id
                    FROM pengajuan_rekening_bantuan
                    GROUP BY siswa_id, istilah
                ) prb2 ON prb1.id = prb2.max_id
            ) prb ON prb.siswa_id = s.peserta_didik_id AND prb.istilah = pb.istilah
            ${whereClause}
            GROUP BY pb.id
            ORDER BY s.nama ASC
        `, params);
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
app.get("/api/bantuan/rombel-siswa", authenticate, async (req, res) => {
  try {
    await ensureLaporanBantuanSchema();
    const { rombel_id, rombel, istilah, tahun, semester } = req.query;
    if (!rombel_id && !rombel) {
      return res.status(400).json({ error: "Parameter rombel_id atau rombel diperlukan" });
    }
    const cleanIstilah = istilah && istilah !== "all" ? String(istilah).trim() : null;
    const cleanTahun = tahun && tahun !== "all" ? String(tahun).trim() : null;
    const cleanSemester = semester && semester !== "all" ? String(semester).trim() : null;
    const [rows] = await getPool().query(`
            SELECT 
                pd.peserta_didik_id as id,
                pd.nama as nama_lengkap,
                COALESCE(pd.nisn, '-') as nisn,
                COALESCE(pd.nik, '-') as nik,
                COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
                rb.nama as rombel,
                rb.rombongan_belajar_id,
                pb.id as existing_pb_id
            FROM anggota_rombel ar
            JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
            JOIN peserta_didik pd ON (pd.peserta_didik_id = ar.peserta_didik_id OR pd.id = ar.peserta_didik_id)
            LEFT JOIN penerima_bantuan pb ON (
                (pb.siswa_id = pd.peserta_didik_id OR pb.siswa_id = pd.id OR pb.siswa_id = pd.nisn OR pb.siswa_id = pd.nik)
                AND (? IS NULL OR pb.istilah = ?)
                AND (? IS NULL OR pb.tahun = ?)
                AND (? IS NULL OR pb.semester = ?)
            )
            WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
              AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')
              AND (rb.rombongan_belajar_id = ? OR rb.nama = ?)
            GROUP BY pd.peserta_didik_id
            ORDER BY pd.nama ASC
        `, [
      cleanIstilah,
      cleanIstilah,
      cleanTahun,
      cleanTahun,
      cleanSemester,
      cleanSemester,
      rombel_id || "",
      rombel || ""
    ]);
    const mapped = (rows || []).map((r) => ({
      id: r.id,
      nama_lengkap: r.nama_lengkap,
      nisn: r.nisn,
      nik: r.nik,
      jenis_kelamin: r.jenis_kelamin,
      rombel: r.rombel,
      rombongan_belajar_id: r.rombongan_belajar_id,
      already_registered: !!r.existing_pb_id
    }));
    res.json(mapped);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
app.post("/api/bantuan/penerima/batch", authenticate, async (req, res) => {
  await ensureLaporanBantuanSchema();
  const { siswa_ids, istilah, tahun, semester, nominal, bank_rekomendasi, items_barang } = req.body;
  if (!Array.isArray(siswa_ids) || siswa_ids.length === 0) {
    return res.status(400).json({ error: "Daftar siswa (siswa_ids) harus berupa array dan tidak boleh kosong" });
  }
  if (!istilah) {
    return res.status(400).json({ error: "Jenis bantuan (istilah) harus diisi" });
  }
  const conn = await getPool().getConnection();
  try {
    await conn.beginTransaction();
    const [jbRows] = await conn.query(
      "SELECT kategori, metode_penyaluran, default_bank, default_nominal, default_items FROM jenis_bantuan WHERE istilah = ?",
      [istilah]
    );
    const jb = jbRows.length > 0 ? jbRows[0] : null;
    const finalNominal = nominal !== void 0 && nominal !== "" && nominal !== null ? parseFloat(String(nominal).replace(/[^0-9.]/g, "")) : jb?.default_nominal ? parseFloat(jb.default_nominal) : null;
    const finalBank = bank_rekomendasi || jb?.default_bank || null;
    const finalItems = items_barang ? typeof items_barang === "object" ? JSON.stringify(items_barang) : String(items_barang) : jb?.default_items || null;
    const cleanTahun = tahun ? String(tahun).trim() : null;
    const cleanSemester = semester ? String(semester).trim() : null;
    const placeholders = siswa_ids.map(() => "?").join(",");
    const checkParams = [...siswa_ids, istilah];
    let checkSql = `SELECT siswa_id FROM penerima_bantuan WHERE siswa_id IN (${placeholders}) AND istilah = ?`;
    if (cleanTahun) {
      checkSql += " AND tahun = ?";
      checkParams.push(cleanTahun);
    } else {
      checkSql += ' AND (tahun IS NULL OR tahun = "")';
    }
    if (cleanSemester) {
      checkSql += " AND semester = ?";
      checkParams.push(cleanSemester);
    } else {
      checkSql += ' AND (semester IS NULL OR semester = "")';
    }
    const [existingRows] = await conn.query(checkSql, checkParams);
    const existingSet = new Set((existingRows || []).map((r) => String(r.siswa_id)));
    const toInsert = siswa_ids.filter((sid) => !existingSet.has(String(sid)));
    let insertedCount = 0;
    for (const sid of toInsert) {
      await conn.query(
        `INSERT INTO penerima_bantuan (siswa_id, istilah, tahun, semester, nominal, bank_rekomendasi, items_barang) VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [sid, istilah, cleanTahun, cleanSemester, finalNominal, finalBank, finalItems]
      );
      insertedCount++;
    }
    await conn.commit();
    res.json({
      success: true,
      total: siswa_ids.length,
      inserted: insertedCount,
      skipped: existingSet.size,
      message: `Berhasil mendaftarkan ${insertedCount} siswa ke bantuan ${istilah}${existingSet.size > 0 ? ` (${existingSet.size} siswa dilewati karena sudah terdaftar)` : ""}.`
    });
  } catch (err) {
    await conn.rollback();
    res.status(500).json({ error: err.message });
  } finally {
    conn.release();
  }
});
