app.post("/api/system/restart-pm2", authenticate, async (req, res) => {
  try {
    res.json({ success: true, message: "Server sedang direstart. Mohon tunggu 5-10 detik." });
    setTimeout(() => {
      try {
        const fsExt = require("fs");
        const path2 = require("path");
        const tmpDir = path2.join(process.cwd(), "tmp");
        if (!fsExt.existsSync(tmpDir)) fsExt.mkdirSync(tmpDir);
        fsExt.writeFileSync(path2.join(tmpDir, "restart.txt"), String(Date.now()));
        console.log("[SYSTEM] Memicu restart server (PM2/cPanel)...");
        if (process.env.pm_id) {
          require("child_process").exec(`pm2 restart ${process.env.pm_id}`, (err) => {
            if (err) process.exit(1);
          });
        } else {
          process.exit(1);
        }
      } catch (err) {
        console.error("[SYSTEM] Restart error:", err);
      }
    }, 1e3);
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});
app.post("/api/upload", authenticate, (req, res, next) => {
  upload.single("file")(req, res, async (err) => {
    if (err) {
      console.error("Multer error:", err);
      return res.status(400).json({ error: err.message || "File upload error" });
    }
    if (!req.file) return res.status(400).json({ error: "No file uploaded" });
    let fileUrl = `/uploads/${req.file.filename}`;
    const gdLink = await uploadToGoogleDriveFallback(req.file.path, req.file.filename, req.file.mimetype, "umum", "Upload Umum");
    if (gdLink) {
      fileUrl = gdLink;
    }
    res.json({ url: fileUrl });
  });
});
app.post("/api/profile/photo", authenticate, (req, res, next) => {
  uploadProfile.single("photo")(req, res, async (err) => {
    if (err) return res.status(400).json({ error: err.message || "File upload error" });
    if (!req.file) return res.status(400).json({ error: "No file uploaded" });
    try {
      const photoUrl = `/uploads/profiles/${req.file.filename}`;
      await getPool().execute("UPDATE pengguna_web SET foto_profil = ? WHERE id = ?", [photoUrl, req.user.id]);
      let staffId = req.user.staff_id;
      if (req.user.type === "staff" && !staffId) {
        const [pw] = await getPool().execute("SELECT staff_id FROM pengguna_web WHERE id = ?", [req.user.id]);
        if (pw.length) staffId = pw[0].staff_id;
      }
      if (staffId) {
        await getPool().execute(`INSERT INTO file_storage (data_id, tipe_data, kategori, server, drive) 
                    VALUES (?, 'pegawai', 'foto_profil', ?, NULL) 
                    ON DUPLICATE KEY UPDATE server = VALUES(server), drive = NULL`, [staffId, photoUrl]);
      } else if (req.user.type === "student") {
        await getPool().execute(`INSERT INTO file_storage (data_id, tipe_data, kategori, server, drive) 
                    VALUES (?, 'siswa', 'foto_profil', ?, NULL) 
                    ON DUPLICATE KEY UPDATE server = VALUES(server), drive = NULL`, [req.user.id, photoUrl]);
      }
      res.json({ photo_url: photoUrl });
    } catch (error) {
      console.error("Profile photo update error:", error);
      res.status(500).json({ error: "Failed to update profile photo" });
    }
  });
});
var handleSelfPasswordChange = async (req, res) => {
  const oldPassword = (req.body.oldPassword || req.body.old_password || req.body.password_lama || "").toString().trim();
  const newPassword = (req.body.newPassword || req.body.new_password || req.body.password_baru || "").toString().trim();
  if (!newPassword || newPassword.length < 6) {
    return res.status(400).json({ error: "Password baru minimal 6 karakter." });
  }
  if (!oldPassword) {
    return res.status(400).json({ error: "Password lama wajib diisi." });
  }
  if (req.user.type === "pelatih") {
    const identifier = req.user.username || String(req.user.id);
    const [authRows] = await getPool().execute(
      "SELECT password FROM pelatih_auth WHERE nik = ? OR nik = ? LIMIT 1",
      [identifier, String(req.user.id)]
    );
    let isMatch = false;
    if (authRows.length > 0) {
      isMatch = await import_bcryptjs.default.compare(oldPassword, authRows[0].password) || oldPassword === authRows[0].password;
    } else {
      isMatch = oldPassword === identifier || oldPassword === String(req.user.id);
    }
    if (!isMatch) {
      return res.status(400).json({ error: "Password lama salah." });
    }
    const hashed2 = await import_bcryptjs.default.hash(newPassword, 10);
    if (authRows.length > 0) {
      await getPool().execute(
        "UPDATE pelatih_auth SET password = ? WHERE nik = ? OR nik = ?",
        [hashed2, identifier, String(req.user.id)]
      );
    } else {
      await getPool().execute(
        "INSERT INTO pelatih_auth (nik, password) VALUES (?, ?) ON DUPLICATE KEY UPDATE password = VALUES(password)",
        [identifier, hashed2]
      );
    }
    try {
      await getPool().execute(
        "UPDATE pengguna_web SET password = ? WHERE username = ? OR staff_id = ?",
        [hashed2, identifier, req.user.id]
      );
    } catch (e) {
    }
    return res.json({ success: true, message: "Password login berhasil diperbarui." });
  }
  let [rows] = await getPool().execute(`
        SELECT wu.*, r.name as role_name 
        FROM pengguna_web wu
        LEFT JOIN peran r ON wu.role_id = r.id
        LEFT JOIN ptk p ON (wu.staff_id = p.ptk_id OR wu.staff_id = p.nik OR wu.username = p.nik OR wu.username = p.nip OR wu.username = p.nuptk)
        LEFT JOIN pegawai pg ON (wu.staff_id = pg.pegawai_id OR wu.staff_id = pg.nik OR wu.username = pg.nik OR wu.username = pg.nip OR wu.username = pg.nuptk)
        WHERE wu.id = ? 
           OR wu.username = ? 
           OR wu.staff_id = ?
           OR p.nik = ? OR p.nip = ? OR p.nuptk = ? OR p.ptk_id = ?
           OR pg.nik = ? OR pg.nip = ? OR pg.nuptk = ? OR pg.pegawai_id = ?
        ORDER BY wu.status_aktif DESC, wu.id ASC
        LIMIT 1
    `, [
    req.user.id,
    req.user.username || "",
    req.user.staff_id || req.user.id || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || "",
    req.user.username || ""
  ]);
  let matchedUser = rows.length > 0 ? rows[0] : null;
  const getValidDefaults = async (userId, staffId, uname) => {
    const defaults2 = [
      "123456",
      "password123",
      "admin123",
      "admin",
      process.env.ADMIN_PASSWORD || "admin123"
    ];
    if (uname) defaults2.push(String(uname).trim());
    if (staffId) defaults2.push(String(staffId).trim());
    if (userId) defaults2.push(String(userId).trim());
    const ids = [userId, staffId, uname, req.user.nik, req.user.nip, req.user.nuptk].filter(Boolean);
    if (ids.length > 0) {
      try {
        const placeholders = ids.map(() => "?").join(",");
        const [ptkRows] = await getPool().query(
          `SELECT nik, nip, nuptk, tanggal_lahir FROM ptk WHERE ptk_id IN (${placeholders}) OR nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) LIMIT 1`,
          [...ids, ...ids, ...ids, ...ids]
        );
        if (ptkRows && ptkRows.length > 0) {
          const p = ptkRows[0];
          if (p.nik) defaults2.push(String(p.nik).trim());
          if (p.nip) defaults2.push(String(p.nip).trim());
          if (p.nuptk) defaults2.push(String(p.nuptk).trim());
          if (p.tanggal_lahir) {
            const d = new Date(p.tanggal_lahir);
            if (!isNaN(d.getTime())) {
              const yyyy = d.getFullYear().toString();
              const mm = String(d.getMonth() + 1).padStart(2, "0");
              const dd = String(d.getDate()).padStart(2, "0");
              defaults2.push(`${yyyy}-${mm}-${dd}`);
              defaults2.push(`${dd}-${mm}-${yyyy}`);
              defaults2.push(`${dd}${mm}${yyyy}`);
              defaults2.push(`${yyyy}${mm}${dd}`);
            }
          }
        }
      } catch (e) {
      }
      try {
        const placeholders = ids.map(() => "?").join(",");
        const [pgRows] = await getPool().query(
          `SELECT nik, nip, nuptk, tanggal_lahir FROM pegawai WHERE pegawai_id IN (${placeholders}) OR nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) LIMIT 1`,
          [...ids, ...ids, ...ids, ...ids]
        );
        if (pgRows && pgRows.length > 0) {
          const p = pgRows[0];
          if (p.nik) defaults2.push(String(p.nik).trim());
          if (p.nip) defaults2.push(String(p.nip).trim());
          if (p.nuptk) defaults2.push(String(p.nuptk).trim());
          if (p.tanggal_lahir) {
            const d = new Date(p.tanggal_lahir);
            if (!isNaN(d.getTime())) {
              const yyyy = d.getFullYear().toString();
              const mm = String(d.getMonth() + 1).padStart(2, "0");
              const dd = String(d.getDate()).padStart(2, "0");
              defaults2.push(`${yyyy}-${mm}-${dd}`);
              defaults2.push(`${dd}-${mm}-${yyyy}`);
              defaults2.push(`${dd}${mm}${yyyy}`);
              defaults2.push(`${yyyy}${mm}${dd}`);
            }
          }
        }
      } catch (e) {
      }
    }
    return defaults2.filter(Boolean);
  };
  if (matchedUser) {
    let isMatch = await import_bcryptjs.default.compare(oldPassword, matchedUser.password);
    if (!isMatch && oldPassword === matchedUser.password) {
      isMatch = true;
    }
    if (!isMatch) {
      const defaults2 = await getValidDefaults(matchedUser.id, matchedUser.staff_id, matchedUser.username);
      if (defaults2.includes(oldPassword)) {
        isMatch = true;
      }
    }
    if (!isMatch) {
      return res.status(400).json({ error: "Password lama salah." });
    }
    const hashed2 = await import_bcryptjs.default.hash(newPassword, 10);
    await getPool().execute("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashed2, matchedUser.id]);
    return res.json({ success: true, message: "Password login akun berhasil diperbarui!" });
  }
  const defaults = await getValidDefaults(req.user.id, req.user.staff_id, req.user.username);
  if (!defaults.includes(oldPassword)) {
    return res.status(400).json({ error: "Password lama salah." });
  }
  let roleId = 2;
  try {
    const [roleRows] = await getPool().query("SELECT id FROM peran WHERE name LIKE '%Guru%' OR name LIKE '%Pegawai%' LIMIT 1");
    if (roleRows && roleRows.length > 0) roleId = roleRows[0].id;
  } catch (e) {
  }
  const hashed = await import_bcryptjs.default.hash(newPassword, 10);
  const newUsername = req.user.username || req.user.nik || req.user.nip || `guru_${Date.now()}`;
  const targetStaffId = req.user.staff_id || req.user.id || null;
  await getPool().execute(
    "INSERT INTO pengguna_web (staff_id, role_id, username, password, status_aktif) VALUES (?, ?, ?, ?, 1)",
    [targetStaffId, roleId, newUsername, hashed]
  );
  return res.json({ success: true, message: "Password login akun berhasil diperbarui!" });
};
