app.get("/api/dashboard-stats", authenticate, asyncHandler(async (req, res) => {
  const stats = {
    student_by_rombel: [],
    student_by_gender: [],
    student_by_religion: [],
    staff_by_status: [],
    staff_by_position: []
  };
  try {
    let whereCondition = `WHERE (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') 
                              AND (rpd.peserta_didik_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM registrasi_peserta_didik LIMIT 1))`;
    let joinClause = `LEFT JOIN (
            SELECT ar.peserta_didik_id, 
                   SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(rb.nama, '') ORDER BY COALESCE(rb.semester_id, '0') DESC SEPARATOR '|||'), '|||', 1) as nama
            FROM anggota_rombel ar 
            JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id 
            WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') 
              AND (rb.soft_delete = 0 OR rb.soft_delete IS NULL OR rb.soft_delete = '0')
            GROUP BY ar.peserta_didik_id
        ) ar_data ON pd.peserta_didik_id = ar_data.peserta_didik_id
        LEFT JOIN (
            SELECT peserta_didik_id 
            FROM registrasi_peserta_didik 
            WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') 
              AND (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
        ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id`;
    const params = [];
    if (req.user.type === "staff") {
      const perms = req.user.permissions || [];
      if (!perms.includes("all") && req.user.staff_id) {
        try {
          const [rombelRows] = await getPool().execute("SELECT nama FROM rombongan_belajar WHERE wali_kelas_id = ?", [req.user.staff_id]);
          if (rombelRows.length > 0) {
            const names = rombelRows.map((r) => r.nama);
            whereCondition += ` AND ar_data.nama IN (${names.map(() => "?").join(",")})`;
            params.push(...names);
          } else {
            whereCondition += ` AND ar_data.nama = 'INVALID_NO_ROMBEL'`;
          }
        } catch (e) {
        }
      }
    }
    try {
      const [rombongan_belajar] = await getPool().execute(`SELECT ar_data.nama as name, COUNT(pd.peserta_didik_id) as value FROM peserta_didik pd ${joinClause} ${whereCondition} GROUP BY ar_data.nama`, params);
      stats.student_by_rombel = (rombongan_belajar || []).map((r) => ({ rombel_name: r.name || "Belum Masuk Rombel", total: Number(r.value) }));
    } catch (e) {
    }
    try {
      const genderJoin = params.length > 0 ? joinClause : `LEFT JOIN (
                SELECT peserta_didik_id 
                FROM registrasi_peserta_didik 
                WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') 
                  AND (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
            ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id`;
      const [gender] = await getPool().execute(`SELECT pd.jenis_kelamin as name, COUNT(pd.peserta_didik_id) as value FROM peserta_didik pd ${genderJoin} ${whereCondition} GROUP BY pd.jenis_kelamin`, params);
      stats.student_by_gender = (gender || []).map((g) => ({ gender: g.name === "L" ? "Laki-laki" : g.name === "P" ? "Perempuan" : "N/A", total: Number(g.value) }));
    } catch (e) {
    }
    try {
      const religionJoin = params.length > 0 ? joinClause : `LEFT JOIN (
                SELECT peserta_didik_id 
                FROM registrasi_peserta_didik 
                WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') 
                  AND (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
            ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id`;
      const [agama] = await getPool().execute(`SELECT pd.agama_id as name, COUNT(pd.peserta_didik_id) as value FROM peserta_didik pd ${religionJoin} ${whereCondition} GROUP BY pd.agama_id`, params);
      const agamaMap = { 1: "Islam", 2: "Kristen", 3: "Katolik", 4: "Hindu", 5: "Buddha", 6: "Khonghucu", 98: "Kepercayaan", 99: "Lainnya" };
      stats.student_by_religion = (agama || []).map((r) => ({ agama: agamaMap[r.name] || "Islam", total: Number(r.value) }));
    } catch (e) {
    }
    try {
      const [staffStatus] = await getPool().execute("SELECT status_kepegawaian as name, COUNT(*) as value FROM ptk WHERE jenis_ptk NOT LIKE '%Pengawas%' OR jenis_ptk IS NULL GROUP BY status_kepegawaian");
      stats.staff_by_status = (staffStatus || []).map((s) => ({ status_kepegawaian: s.name || "Belum Diatur", total: Number(s.value) }));
    } catch (e) {
    }
    try {
      const [jabatan] = await getPool().execute("SELECT jenis_ptk as name, COUNT(*) as value FROM ptk WHERE jenis_ptk NOT LIKE '%Pengawas%' OR jenis_ptk IS NULL GROUP BY jenis_ptk");
      stats.staff_by_position = (jabatan || []).map((j) => ({ jabatan: j.name || "N/A", total: Number(j.value) }));
    } catch (e) {
    }
    stats.total_students = stats.student_by_gender.reduce((acc, g) => acc + (g.total || 0), 0);
    stats.total_staff = stats.staff_by_status.reduce((acc, s) => acc + (s.total || 0), 0);
    try {
      const [rbCount] = await getPool().execute(
        "SELECT COUNT(*) as cnt FROM rombongan_belajar WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')"
      );
      stats.total_rombels = Number(rbCount[0]?.cnt || 0);
    } catch (e) {
      stats.total_rombels = stats.student_by_rombel?.length || 0;
    }
    try {
      const [annCount] = await getPool().execute(
        "SELECT COUNT(*) as cnt FROM pengumuman WHERE status = 'published'"
      );
      stats.total_announcements = Number(annCount[0]?.cnt || 0);
    } catch (e) {
      stats.total_announcements = 0;
    }
  } catch (error) {
    console.error("[ERROR] Failed to fetch dashboard stats:", error);
  }
  res.json(stats);
}));
