app.post("/api/kalender_akademik/hitung_hari_efektif", asyncHandler(async (req, res) => {
  const { start_date, end_date, include_saturday } = req.body;
  if (!start_date) return res.status(400).json({ error: "start_date wajib diisi" });
  const sKey = String(start_date).split("T")[0];
  const eKey = end_date ? String(end_date).split("T")[0] : sKey;
  const [rows] = await getPool().execute(
    `SELECT * FROM kalender_akademik 
         WHERE (is_libur = 1 OR category = 'Libur Nasional' OR category LIKE '%Libur%' OR category = 'Holiday')
           AND ((event_date BETWEEN ? AND ?) OR (end_date IS NOT NULL AND end_date >= ? AND event_date <= ?))`,
    [sKey, eKey, sKey, eKey]
  );
  const holidaySet = /* @__PURE__ */ new Map();
  for (const item of rows) {
    const itemStart = new Date(item.event_date);
    const itemEnd = item.end_date ? new Date(item.end_date) : itemStart;
    for (let d = new Date(itemStart); d <= itemEnd; d.setDate(d.getDate() + 1)) {
      const dStr = d.toISOString().split("T")[0];
      holidaySet.set(dStr, { title: item.title, category: item.category || "Libur" });
    }
  }
  const s = new Date(sKey);
  const e = new Date(eKey);
  const [startObj, endObj] = s <= e ? [s, e] : [e, s];
  let hariSekolah = 0;
  let totalKalender = 0;
  let weekendCount = 0;
  let liburCount = 0;
  const rincianLibur = [];
  for (let d = new Date(startObj); d <= endObj; d.setDate(d.getDate() + 1)) {
    totalKalender++;
    const dayOfWeek = d.getDay();
    const dStr = d.toISOString().split("T")[0];
    const isSunday = dayOfWeek === 0;
    const isSaturday = dayOfWeek === 6 && !include_saturday;
    if (isSunday || isSaturday) {
      weekendCount++;
      continue;
    }
    if (holidaySet.has(dStr)) {
      const h = holidaySet.get(dStr);
      liburCount++;
      rincianLibur.push({ tanggal: dStr, title: h.title, category: h.category });
      continue;
    }
    hariSekolah++;
  }
  res.json({
    hari_sekolah: Math.max(1, hariSekolah),
    total_kalender: Math.max(1, totalKalender),
    weekend_count: weekendCount,
    libur_count: liburCount,
    rincian_libur: rincianLibur
  });
}));
