app.get("/api/wilayah/regencies", asyncHandler(async (req, res) => {
  const { province_id, provinsi } = req.query;
  try {
    const pool2 = getPool();
    let targetKode = (province_id || "").trim();
    if (!targetKode && provinsi) {
      const pName = String(provinsi).trim();
      const [pRows] = await pool2.query(
        "SELECT kode_wilayah FROM ref_mst_wilayah WHERE id_level_wilayah = 1 AND (nama LIKE ? OR nama LIKE ?) LIMIT 1",
        [`%${pName}%`, `%${pName.replace(/^prov\.?\s+/i, "")}%`]
      );
      if (pRows.length > 0) targetKode = pRows[0].kode_wilayah.trim();
    }
    if (targetKode) {
      const [rows] = await pool2.query(
        "SELECT kode_wilayah, nama FROM ref_mst_wilayah WHERE id_level_wilayah = 2 AND mst_kode_wilayah LIKE ? ORDER BY nama ASC",
        [`${targetKode}%`]
      );
      if (rows && rows.length > 0) {
        const regencies = rows.map((r) => ({
          id: (r.kode_wilayah || "").trim(),
          name: (r.nama || "").trim().toUpperCase(),
          raw_name: r.nama
        }));
        return res.json(regencies);
      }
    }
  } catch (e) {
    console.warn("Fallback local regencies query error:", e.message);
  }
  res.json([]);
}));
