async function ensureStrukturOrganisasiSchema() {
  try {
    const pool2 = getPool();
    await pool2.query(`
            CREATE TABLE IF NOT EXISTS struktur_organisasi (
                id INT AUTO_INCREMENT PRIMARY KEY,
                pegawai_id VARCHAR(100) DEFAULT NULL,
                nama_lengkap VARCHAR(255) DEFAULT NULL,
                parent_id INT DEFAULT NULL,
                jabatan_struktur VARCHAR(255) NOT NULL,
                urutan INT DEFAULT 0,
                kategori VARCHAR(50) DEFAULT 'struktur',
                rincian_tugas TEXT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        `);
    const columns = [
      { name: "pegawai_id", def: "VARCHAR(100) DEFAULT NULL" },
      { name: "nama_lengkap", def: "VARCHAR(255) DEFAULT NULL" },
      { name: "parent_id", def: "INT DEFAULT NULL" },
      { name: "jabatan_struktur", def: "VARCHAR(255) NOT NULL" },
      { name: "urutan", def: "INT DEFAULT 0" },
      { name: "kategori", def: "VARCHAR(50) DEFAULT 'struktur'" },
      { name: "rincian_tugas", def: "TEXT DEFAULT NULL" }
    ];
    for (const col of columns) {
      try {
        await pool2.query(`ALTER TABLE struktur_organisasi ADD COLUMN \`${col.name}\` ${col.def}`);
      } catch (e) {
      }
    }
  } catch (err) {
    console.warn("[DB] Error ensuring struktur_organisasi schema:", err.message);
  }
}
async function loadResolvedPtkMap() {
  const ptkMap = {};
  try {
    const dynamicGelarMap = {};
    try {
      const [gRows] = await getPool().query("SELECT gelar_akademik_id, kode, nama, posisi_gelar FROM gelar_akademik");
      for (const g of gRows || []) {
        dynamicGelarMap[String(g.gelar_akademik_id)] = {
          kode: g.kode || g.nama || "",
          posisi: g.posisi_gelar
        };
      }
    } catch (e) {
    }
    const rwyGelarMap = {};
    try {
      const [rpfRows] = await getPool().query(`
                SELECT rpf.ptk_id, rpf.gelar_akademik_id, ga.kode as gelar_kode, ga.posisi_gelar
                FROM rwy_pend_formal rpf
                LEFT JOIN gelar_akademik ga ON rpf.gelar_akademik_id = ga.gelar_akademik_id
                WHERE (rpf.soft_delete = 0 OR rpf.soft_delete IS NULL OR rpf.soft_delete = '0')
                ORDER BY CAST(rpf.jenjang_pendidikan_id AS UNSIGNED) DESC, rpf.tahun_lulus DESC
            `);
      for (const r of rpfRows || []) {
        const pId = String(r.ptk_id);
        if (!rwyGelarMap[pId]) {
          rwyGelarMap[pId] = { gelarDepan: "", gelarBelakang: "" };
        }
        const gKode = r.gelar_kode || dynamicGelarMap[String(r.gelar_akademik_id)]?.kode || "";
        const gPosisi = r.posisi_gelar || dynamicGelarMap[String(r.gelar_akademik_id)]?.posisi;
        if (gKode && gKode !== "-") {
          if ((String(gPosisi) === "1" || gKode.startsWith("Dr") || gKode.startsWith("Prof") || gKode.startsWith("Drs") || gKode.startsWith("Dra") || gKode.startsWith("H.") || gKode.startsWith("Hj.")) && !rwyGelarMap[pId].gelarDepan) {
            rwyGelarMap[pId].gelarDepan = gKode;
          } else if (!rwyGelarMap[pId].gelarBelakang && String(gPosisi) !== "1") {
            rwyGelarMap[pId].gelarBelakang = gKode;
          }
        }
      }
    } catch (e) {
    }
    let pRows = [];
    try {
      const [rows] = await getPool().query("SELECT ptk_id, nama, nip, nik, nuptk, gelar_depan, gelar_belakang, jenis_ptk, jenis_ptk_id FROM ptk WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')");
      pRows = rows || [];
    } catch (ePtk) {
      try {
        const [rows] = await getPool().query("SELECT ptk_id, nama, nip, nik, gelar_depan, gelar_belakang, jenis_ptk, jenis_ptk_id FROM ptk WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')");
        pRows = rows || [];
      } catch (ePtk2) {
      }
    }
    for (const p of pRows || []) {
      const pId = String(p.ptk_id).trim();
      const rwy = rwyGelarMap[pId];
      let gDepan = p.gelar_depan;
      if (gDepan === "-" || gDepan === "null" || gDepan === "NULL") {
        gDepan = "";
      } else if (dynamicGelarMap[String(gDepan)]) {
        gDepan = dynamicGelarMap[String(gDepan)].kode;
      } else if ((gDepan === null || gDepan === void 0 || String(gDepan).trim() === "") && rwy?.gelarDepan) {
        gDepan = rwy.gelarDepan;
      } else {
        gDepan = gDepan || "";
      }
      let gBelakang = p.gelar_belakang;
      if (gBelakang === "-" || gBelakang === "null" || gBelakang === "NULL") {
        gBelakang = "";
      } else if (dynamicGelarMap[String(gBelakang)]) {
        gBelakang = dynamicGelarMap[String(gBelakang)].kode;
      } else if ((gBelakang === null || gBelakang === void 0 || String(gBelakang).trim() === "") && rwy?.gelarBelakang) {
        gBelakang = rwy.gelarBelakang;
      } else {
        gBelakang = gBelakang || "";
      }
      let mainName = (p.nama || "").toUpperCase();
      let fullName = mainName;
      if (gDepan && gDepan !== "-") fullName = `${gDepan} ${fullName}`;
      if (gBelakang && gBelakang !== "-") fullName = `${fullName}, ${gBelakang}`;
      const item = { ...p, fullName, gelar_depan: gDepan, gelar_belakang: gBelakang };
      ptkMap[pId] = item;
      if (p.nik) ptkMap[String(p.nik).trim()] = item;
      if (p.nip) ptkMap[String(p.nip).trim()] = item;
      if (p.nuptk) ptkMap[String(p.nuptk).trim()] = item;
    }
  } catch (e) {
    try {
      const [pegRows] = await getPool().query("SELECT pegawai_id, nama_lengkap as nama, nip, nik, gelar_depan, gelar_belakang, jenis_ptk FROM pegawai");
      for (const p of pegRows || []) {
        ptkMap[String(p.pegawai_id)] = { ...p, fullName: (p.nama || "").toUpperCase() };
      }
    } catch (e2) {
    }
  }
  return ptkMap;
}
async function loadStrukturOrganisasiData() {
  await ensureStrukturOrganisasiSchema();
  let strukturRows = [];
  try {
    const [sRows] = await getPool().query("SELECT * FROM struktur_organisasi ORDER BY urutan ASC, id ASC");
    strukturRows = sRows || [];
  } catch (e) {
    return [];
  }
  const ptkMap = await loadResolvedPtkMap();
  const fotoProfilMap = {};
  try {
    const [fRows] = await getPool().query("SELECT data_id, COALESCE(drive, server) as foto_profil FROM file_storage WHERE tipe_data = 'pegawai' AND kategori = 'foto_profil'");
    for (const f of fRows || []) {
      if (f.data_id) fotoProfilMap[String(f.data_id)] = f.foto_profil;
    }
  } catch (e) {
  }
  return strukturRows.map((s) => {
    const pId = String(s.pegawai_id || "");
    const ptk = ptkMap[pId];
    const nama = ptk?.fullName || s.nama_lengkap || ptk?.nama || null;
    const foto = fotoProfilMap[pId] || (ptk?.ptk_id ? fotoProfilMap[String(ptk.ptk_id)] : null) || null;
    const nip = ptk?.nip || s.nip || "";
    return {
      ...s,
      nama_lengkap: nama,
      foto_profil: foto,
      nip
    };
  });
}
