app.post("/api/siswa/:id/bantuan", authenticate, asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { istilah, tahun, semester, nominal, bank_rekomendasi, items_barang } = req.body;
  if (!istilah) {
    return res.status(400).json({ error: "istilah is required" });
  }
  const conn = await getPool().getConnection();
  try {
    await conn.beginTransaction();
    const [existing] = await conn.execute(
      `SELECT id FROM penerima_bantuan WHERE siswa_id = ? AND istilah = ? AND tahun = ? AND semester = ?`,
      [id, istilah, tahun || null, semester || null]
    );
    if (existing.length > 0) {
      await conn.rollback();
      return res.status(400).json({ error: "Siswa sudah menerima bantuan ini pada tahun dan semester yang dipilih." });
    }
    const [jbRows] = await conn.execute(
      "SELECT kategori, metode_penyaluran, default_bank, default_nominal, default_items FROM jenis_bantuan WHERE istilah = ?",
      [istilah]
    );
    const jb = jbRows.length > 0 ? jbRows[0] : null;
    const finalNominal = nominal !== void 0 && nominal !== "" && nominal !== null ? parseFloat(String(nominal).replace(/[^0-9.]/g, "")) : jb?.default_nominal ? parseFloat(jb.default_nominal) : null;
    const finalBank = bank_rekomendasi || jb?.default_bank || null;
    const finalItems = items_barang ? typeof items_barang === "object" ? JSON.stringify(items_barang) : String(items_barang) : jb?.default_items || null;
    await conn.execute(
      `INSERT INTO penerima_bantuan (siswa_id, istilah, tahun, semester, nominal, bank_rekomendasi, items_barang) VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [id, istilah, tahun || null, semester || null, finalNominal, finalBank, finalItems]
    );
    await conn.commit();
    res.json({ success: true });
  } catch (err) {
    await conn.rollback();
    res.status(500).json({ error: err.message });
  } finally {
    conn.release();
  }
}));
app.get("/api/arsip-siswa", authenticate, asyncHandler(async (req, res) => {
  let whereClause = "";
  const params = [];
  try {
    if (req.user.type === "staff") {
      const perms = req.user.permissions || [];
      const isStrictWali = !perms.includes("all") || req.query.wali_only === "true";
      if (isStrictWali) {
        const candidateIds = [req.user.staff_id, req.user.username, req.user.id].filter(Boolean);
        if (candidateIds.length > 0) {
          const placeholders = candidateIds.map(() => "?").join(",");
          const [rombelRows] = await getPool().execute(`
                        SELECT DISTINCT r.nama as name, r.rombongan_belajar_id 
                        FROM rombongan_belajar r
                        WHERE (r.soft_delete = 0 OR r.soft_delete IS NULL OR r.soft_delete = '0' OR r.soft_delete = '')
                          AND (
                            r.ptk_id IN (${placeholders})
                            OR r.wali_kelas_id IN (${placeholders})
                            OR r.ptk_id IN (SELECT ptk_id FROM ptk WHERE nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) OR ptk_id IN (${placeholders}))
                            OR r.ptk_id IN (SELECT ptk_id FROM pegawai WHERE nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) OR pegawai_id IN (${placeholders}))
                          )
                    `, [
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds,
            ...candidateIds
          ]);
          if (rombelRows && rombelRows.length > 0) {
            const names = rombelRows.map((r) => r.name).filter(Boolean);
            if (names.length > 0) {
              whereClause = `WHERE a.rombel IN (${names.map(() => "?").join(",")})`;
              params.push(...names);
            }
          }
        }
      }
    }
  } catch (e) {
  }
  const [rows] = await getPool().execute(`
        SELECT 
            a.*,
            s.peserta_didik_id,
            COALESCE(s.nama, '') AS nama_lengkap,
            COALESCE(s.nama, '') AS nama,
            COALESCE(s.nisn, '') AS nisn,
            COALESCE(s.nik, '') AS nik,
            COALESCE(s.jenis_kelamin, '') AS jenis_kelamin,
            COALESCE(s.tempat_lahir, '') AS tempat_lahir,
            s.tanggal_lahir,
            COALESCE(rpd.nipd, '') AS nipd,
            COALESCE(fs_foto.drive, fs_foto.server) AS foto_profil
        FROM arsip_siswa a
        LEFT JOIN peserta_didik s ON a.siswa_id = s.peserta_didik_id OR a.siswa_id = s.nisn OR a.siswa_id = s.nik
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            GROUP BY peserta_didik_id
        ) rpd ON rpd.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN file_storage fs_foto ON s.peserta_didik_id = fs_foto.data_id AND fs_foto.tipe_data = 'siswa' AND fs_foto.kategori = 'foto_profil'
        ${whereClause}
        ORDER BY a.created_at DESC
    `, params);
  res.json(rows);
}));
