app.get("/api/student/profile", authenticate, asyncHandler(async (req, res) => {
  if (req.user.type !== "student") return res.status(403).json({ error: "Access denied" });
  const id = req.user.id || "not-found";
  const nisn = req.user.nisn || req.user.username || "not-found";
  const [rows] = await getPool().execute(`
        SELECT 
            s.*, s.peserta_didik_id as id, s.nama as nama_lengkap, 
            rpd.nipd as nipd_rpd, 
            rombel_data.rombel, 
            rombel_data.rombongan_belajar_id, 
            rombel_data.semester_id,
            CONCAT(LEFT(COALESCE(rombel_data.semester_id, '20261'), 4), '/', CAST(LEFT(COALESCE(rombel_data.semester_id, '20261'), 4) AS UNSIGNED) + 1) AS tahun_pelajaran,
            IF(RIGHT(COALESCE(rombel_data.semester_id, '1'), 1) = '1', 'Ganjil', 'Genap') AS semester,
            s.nama_ayah, s.nik_ayah, s.tahun_lahir_ayah, 
            s.nama_ibu_kandung as nama_ibu, s.nik_ibu, s.tahun_lahir_ibu, 
            s.nama_wali, s.nik_wali, s.tahun_lahir_wali, 
            s.nomor_telepon_rumah as telepon_rumah, s.nomor_telepon_seluler as hp_orang_tua, s.email as email_orang_tua,
            s.anak_keberapa,
            pdl.tinggi_badan, pdl.berat_badan, pdl.lingkar_kepala, pdl.jarak_rumah_ke_sekolah, pdl.jarak_rumah_ke_sekolah_km, pdl.waktu_tempuh_ke_sekolah, pdl.menit_tempuh_ke_sekolah, pdl.jumlah_saudara_kandung,
            s.no_kks as nomor_kks, s.penerima_kps as penerima_kps_pkh, s.penerima_kip, s.no_kip as nomor_kip, s.nm_kip as nama_sesuai_kip, s.no_kps as nomor_kps, s.id_bank as bank_pip, s.rekening_bank as nomor_rek_pip, s.rekening_atas_nama as atasnama_rek_pip, s.layak_pip, s.id_layak_pip as alasan_layak_pip,
            COALESCE(fs_foto.drive, fs_foto.server) AS foto_profil
         FROM peserta_didik s
        LEFT JOIN (
            SELECT 
                ar.peserta_didik_id,
                SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(rb.nama, '') ORDER BY COALESCE(rb.semester_id, '0') DESC, ar.last_update DESC SEPARATOR '|||'), '|||', 1) as rombel,
                SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(rb.rombongan_belajar_id, '') ORDER BY COALESCE(rb.semester_id, '0') DESC, ar.last_update DESC SEPARATOR '|||'), '|||', 1) as rombongan_belajar_id,
                SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(rb.semester_id, '') ORDER BY COALESCE(rb.semester_id, '0') DESC, ar.last_update DESC SEPARATOR '|||'), '|||', 1) as semester_id
            FROM anggota_rombel ar
            JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
            GROUP BY ar.peserta_didik_id
        ) rombel_data ON rombel_data.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            GROUP BY peserta_didik_id
        ) rpd ON rpd.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN (
            SELECT 
                peserta_didik_id, 
                MAX(tinggi_badan) as tinggi_badan,
                MAX(berat_badan) as berat_badan,
                MAX(lingkar_kepala) as lingkar_kepala,
                MAX(jarak_rumah_ke_sekolah) as jarak_rumah_ke_sekolah,
                MAX(jarak_rumah_ke_sekolah_km) as jarak_rumah_ke_sekolah_km,
                MAX(waktu_tempuh_ke_sekolah) as waktu_tempuh_ke_sekolah,
                MAX(menit_tempuh_ke_sekolah) as menit_tempuh_ke_sekolah,
                MAX(jumlah_saudara_kandung) as jumlah_saudara_kandung
            FROM peserta_didik_longitudinal
            GROUP BY peserta_didik_id
        ) pdl ON pdl.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN (
            SELECT data_id, MAX(drive) as drive, MAX(server) as server
            FROM file_storage
            WHERE tipe_data = 'siswa' AND kategori = 'foto_profil'
            GROUP BY data_id
        ) fs_foto ON s.peserta_didik_id = fs_foto.data_id
        WHERE s.peserta_didik_id = ? OR s.nisn = ?
        LIMIT 1
    `, [id, nisn]);
  if (!rows || rows.length === 0) return res.json(null);
  const r = rows[0];
  const [agamaMap, pekMap, pendMap, pengMap, jtMap, atMap, kkMap] = await Promise.all([
    getRefMapSafe("agama", "agama_id", "nama", AGAMA_DEFAULT_MAP),
    getRefMapSafe("pekerjaan", "pekerjaan_id", "nama", PEKERJAAN_DEFAULT_MAP),
    getRefMapSafe("jenjang_pendidikan", "jenjang_pendidikan_id", "nama", PENDIDIKAN_DEFAULT_MAP),
    getRefMapSafe("penghasilan", "penghasilan_id", "nama", PENGHASILAN_DEFAULT_MAP),
    getRefMapSafe("jenis_tinggal", "jenis_tinggal_id", "nama", JENIS_TINGGAL_DEFAULT_MAP),
    getRefMapSafe("alat_transportasi", "alat_transportasi_id", "nama", ALAT_TRANSPORTASI_DEFAULT_MAP),
    getRefMapSafe("kebutuhan_khusus", "kebutuhan_khusus_id", "nama", KEBUTUHAN_KHUSUS_DEFAULT_MAP)
  ]);
  res.json({
    ...r,
    nipd: r.nipd_rpd || r.nipd || "",
    rombel: r.rombel || "",
    agama: (r.agama_id ? agamaMap[String(r.agama_id)] : null) || r.agama || "-",
    pekerjaan_ayah: (r.pekerjaan_id_ayah !== null && r.pekerjaan_id_ayah !== void 0 ? pekMap[String(r.pekerjaan_id_ayah)] : null) || r.pekerjaan_ayah || "-",
    penghasilan_ayah: (r.penghasilan_id_ayah !== null && r.penghasilan_id_ayah !== void 0 ? pengMap[String(r.penghasilan_id_ayah)] : null) || r.penghasilan_ayah || "-",
    pendidikan_ayah: (r.jenjang_pendidikan_ayah !== null && r.jenjang_pendidikan_ayah !== void 0 ? pendMap[String(r.jenjang_pendidikan_ayah)] : null) || r.pendidikan_ayah || "-",
    pekerjaan_ibu: (r.pekerjaan_id_ibu !== null && r.pekerjaan_id_ibu !== void 0 ? pekMap[String(r.pekerjaan_id_ibu)] : null) || r.pekerjaan_ibu || "-",
    penghasilan_ibu: (r.penghasilan_id_ibu !== null && r.penghasilan_id_ibu !== void 0 ? pengMap[String(r.penghasilan_id_ibu)] : null) || r.penghasilan_ibu || "-",
    pendidikan_ibu: (r.jenjang_pendidikan_ibu !== null && r.jenjang_pendidikan_ibu !== void 0 ? pendMap[String(r.jenjang_pendidikan_ibu)] : null) || r.pendidikan_ibu || "-",
    pekerjaan_wali: (r.pekerjaan_id_wali !== null && r.pekerjaan_id_wali !== void 0 ? pekMap[String(r.pekerjaan_id_wali)] : null) || r.pekerjaan_wali || "-",
    penghasilan_wali: (r.penghasilan_id_wali !== null && r.penghasilan_id_wali !== void 0 ? pengMap[String(r.penghasilan_id_wali)] : null) || r.penghasilan_wali || "-",
    pendidikan_wali: (r.jenjang_pendidikan_wali !== null && r.jenjang_pendidikan_wali !== void 0 ? pendMap[String(r.jenjang_pendidikan_wali)] : null) || r.pendidikan_wali || "-",
    tempat_tinggal: (r.jenis_tinggal_id ? jtMap[String(r.jenis_tinggal_id)] : null) || r.tempat_tinggal || "-",
    moda_transportasi: (r.alat_transportasi_id ? atMap[String(r.alat_transportasi_id)] : null) || r.moda_transportasi || "-",
    kebutuhan_khusus: (r.kebutuhan_khusus_id ? kkMap[String(r.kebutuhan_khusus_id)] : null) || r.kebutuhan_khusus || "-"
  });
}));
app.post("/api/student/profile/photo", authenticate, uploadProfile.single("photo"), asyncHandler(async (req, res) => {
  if (req.user.type !== "student") return res.status(403).json({ error: "Access denied" });
  if (!req.file) return res.status(400).json({ error: "No file uploaded" });
  const id = req.user.id || null;
  const nisn = req.user.nisn || req.user.username || null;
  const [rows] = await getPool().execute("SELECT id, nipd, nik, nama_lengkap FROM peserta_didik WHERE peserta_didik_id = ? OR nisn = ?", [id, nisn]);
  if (rows.length === 0) return res.status(404).json({ error: "Siswa not found" });
  const actualId = rows[0].id;
  const nik = rows[0].nik || rows[0].nipd || `siswa_${actualId}`;
  const nama = rows[0].nama_lengkap || "Siswa";
  const safeName = `${nik}_${nama}`.replace(/[^a-zA-Z0-9_-]/g, "_");
  const ext = import_path.default.extname(req.file.originalname);
  const newFileName = `${safeName}${ext}`;
  const newPath = import_path.default.join(uploadDir, "profiles", "siswa", newFileName);
  import_fs.default.renameSync(req.file.path, newPath);
  let serverLink = `/uploads/profiles/siswa/${newFileName}`;
  let driveLink = null;
  const gdLink = await uploadToGoogleDriveFallback(newPath, newFileName, req.file.mimetype, "siswa", "Foto Profil Siswa");
  if (gdLink) {
    driveLink = gdLink;
    serverLink = null;
  }
  await getPool().execute(
    `INSERT INTO file_storage (data_id, tipe_data, kategori, server, drive) 
         VALUES (?, 'siswa', 'foto_profil', ?, ?) 
         ON DUPLICATE KEY UPDATE server = VALUES(server), drive = VALUES(drive)`,
    [actualId, serverLink, driveLink]
  );
  res.json({ message: "Photo uploaded successfully", photo_url: driveLink || serverLink });
}));
app.get("/api/student/absensi", authenticate, asyncHandler(async (req, res) => {
  if (req.user.type !== "student") return res.status(403).json({ error: "Access denied" });
  const id = req.user.id || "not-found";
  const { start_date, end_date } = req.query;
  let dateFilter = "";
  const params = [id];
  if (start_date && end_date) {
    dateFilter = "AND tanggal >= ? AND tanggal <= ?";
    params.push(start_date, end_date);
  }
  const [rows] = await getPool().execute(`
        SELECT status, COUNT(*) as count 
        FROM absensi_siswa 
        WHERE student_id = ? ${dateFilter}
        GROUP BY status
    `, params);
  const [records] = await getPool().execute(`
        SELECT tanggal, status, keterangan 
        FROM absensi_siswa 
        WHERE student_id = ? ${dateFilter}
        ORDER BY tanggal DESC
    `, params);
  res.json({ summary: rows, records });
}));
