app.get("/api/permohonan-pindah", authenticate, asyncHandler(async (req, res) => {
  const [rows] = await getPool().execute(`
        SELECT pp.*, COALESCE(s.nama, s.nama_lengkap) as nama, COALESCE(s.nama, s.nama_lengkap) as nama_lengkap, 
               s.nisn, s.tempat_lahir, s.tanggal_lahir, s.agama_id, s.jenis_kelamin,
               COALESCE(rb.nama, '') as rombel, rb.tingkat_pendidikan_id, rb.semester_id
        FROM permohonan_pindah pp
        JOIN peserta_didik s ON pp.student_id = s.peserta_didik_id
        LEFT JOIN anggota_rombel ar ON (s.peserta_didik_id = ar.peserta_didik_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0'))
        LEFT JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id
        GROUP BY pp.id
        ORDER BY pp.created_at DESC
    `);
  res.json(rows);
}));
app.post("/api/permohonan-pindah", authenticate, asyncHandler(async (req, res) => {
  let student_id;
  if (req.user.type === "student") {
    student_id = req.user.id;
  } else {
    if (!req.body.student_id) return res.status(400).json({ error: "student_id is required" });
    student_id = req.body.student_id;
  }
  const { wali_nama, wali_pekerjaan, wali_alamat, tujuan_sekolah, tujuan_desa, tujuan_kec, tujuan_kota, tujuan_prov, alasan } = req.body;
  const [existing] = await getPool().execute("SELECT id FROM permohonan_pindah WHERE student_id = ? AND status = 'menunggu'", [student_id]);
  if (existing.length > 0) {
    return res.status(400).json({ error: "Siswa ini sudah memiliki pengajuan yang sedang diproses." });
  }
  await getPool().execute(`
        INSERT INTO permohonan_pindah 
        (student_id, wali_nama, wali_pekerjaan, wali_alamat, tujuan_sekolah, tujuan_desa, tujuan_kec, tujuan_kota, tujuan_prov, alasan, status)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'menunggu')
    `, [student_id, wali_nama, wali_pekerjaan, wali_alamat, tujuan_sekolah, tujuan_desa, tujuan_kec, (tujuan_kota || "").trim(), (tujuan_prov || "").trim(), alasan]);
  res.json({ success: true });
}));
