async function resolveMailboxName(client, requestedFolder) {
  const cleanReq = (requestedFolder || "INBOX").trim();
  if (cleanReq.toUpperCase() === "INBOX") return "INBOX";
  try {
    const mailboxes = await client.list();
    if (cleanReq.toLowerCase() === "sent") {
      const match = mailboxes.find(
        (m) => m.specialUse === "\\Sent" || m.path.toLowerCase() === "inbox.sent" || m.path.toLowerCase() === "sent" || m.path.toLowerCase() === "sent messages" || m.path.toLowerCase() === "sent items" || m.name.toLowerCase() === "sent"
      );
      if (match) return match.path;
    }
    if (cleanReq.toLowerCase() === "trash") {
      const match = mailboxes.find(
        (m) => m.specialUse === "\\Trash" || m.path.toLowerCase() === "inbox.trash" || m.path.toLowerCase() === "trash" || m.path.toLowerCase() === "deleted messages" || m.path.toLowerCase() === "deleted items" || m.name.toLowerCase() === "trash"
      );
      if (match) return match.path;
    }
    if (cleanReq.toLowerCase() === "drafts") {
      const match = mailboxes.find(
        (m) => m.specialUse === "\\Drafts" || m.path.toLowerCase() === "inbox.drafts" || m.path.toLowerCase() === "drafts" || m.name.toLowerCase() === "drafts"
      );
      if (match) return match.path;
    }
    const directMatch = mailboxes.find((m) => m.path.toLowerCase() === cleanReq.toLowerCase() || m.name.toLowerCase() === cleanReq.toLowerCase());
    if (directMatch) return directMatch.path;
  } catch (e) {
    console.warn("[Mailbox Resolve Error]:", e);
  }
  return cleanReq;
}
app.get("/api/webmail/messages", authenticate, asyncHandler(async (req, res) => {
  try {
    const creds = await getUserEmailCredentials(getPool(), req.user, req.query.email);
    const rawFolder = (req.query.folder || "INBOX").trim();
    const page = Math.max(1, parseInt(req.query.page || "1", 10));
    const limit = Math.min(100, Math.max(5, parseInt(req.query.limit || "30", 10)));
    const search = req.query.search ? String(req.query.search).trim() : "";
    if (rawFolder.toLowerCase() === "drafts" || rawFolder.toLowerCase() === "draf") {
      const p = getPool();
      let countQuery = "SELECT COUNT(*) as total FROM webmail_drafts WHERE user_email = ?";
      let selectQuery = "SELECT * FROM webmail_drafts WHERE user_email = ?";
      const queryParams = [creds.email];
      const countParams = [creds.email];
      if (search) {
        const searchPattern = `%${search}%`;
        countQuery += " AND (subject LIKE ? OR to_recipients LIKE ? OR body_text LIKE ?)";
        countParams.push(searchPattern, searchPattern, searchPattern);
        selectQuery += " AND (subject LIKE ? OR to_recipients LIKE ? OR body_text LIKE ?)";
        queryParams.push(searchPattern, searchPattern, searchPattern);
      }
      selectQuery += " ORDER BY updated_at DESC LIMIT ? OFFSET ?";
      const offset = (page - 1) * limit;
      queryParams.push(limit, offset);
      const [cntRows] = await p.query(countQuery, countParams);
      const total = cntRows?.[0]?.total || 0;
      const [rows] = await p.query(selectQuery, queryParams);
      const draftMessages = (rows || []).map((row) => ({
        uid: row.id,
        id: row.id,
        isDraft: true,
        from: creds.email,
        fromName: "Saya (Draf)",
        fromEmail: creds.email,
        to: row.to_recipients || "(Tanpa Penerima)",
        cc: row.cc_recipients || "",
        bcc: row.bcc_recipients || "",
        subject: row.subject || "(Tanpa Subjek)",
        date: row.updated_at || row.created_at,
        flags: ["\\Draft"],
        isUnread: false,
        isFlagged: false,
        size: (row.body_text?.length || 0) + (row.body_html?.length || 0),
        hasAttachments: false,
        text: row.body_text || "",
        html: row.body_html || ""
      }));
      return res.json({
        success: true,
        folder: "Drafts",
        realFolder: "Drafts",
        total,
        unseen: 0,
        page,
        limit,
        messages: draftMessages
      });
    }
    const client = await createImapClient(creds);
    try {
      const folder = await resolveMailboxName(client, rawFolder);
      const lock = await client.getMailboxLock(folder);
      try {
        const mailboxExists = lock?.mailbox?.exists ?? client?.mailbox?.exists;
        let totalMessages = typeof mailboxExists === "number" ? mailboxExists : 0;
        if (!totalMessages) {
          const status = await client.status(folder, { messages: true }).catch(() => ({ messages: 0 }));
          totalMessages = status.messages || 0;
        }
        const unseenStatus = await client.status(folder, { unseen: true }).catch(() => ({ unseen: 0 }));
        const unseenCount = unseenStatus.unseen || 0;
        if (totalMessages === 0) {
          return res.json({
            success: true,
            folder: rawFolder,
            realFolder: folder,
            total: 0,
            unseen: 0,
            page,
            limit,
            messages: []
          });
        }
        const startIndex = Math.max(1, totalMessages - page * limit + 1);
        const endIndex = Math.max(1, totalMessages - (page - 1) * limit);
        const range = `${startIndex}:${endIndex}`;
        const messages = [];
        for await (const msg of client.fetch(range, {
          uid: true,
          envelope: true,
          flags: true,
          size: true,
          bodyStructure: true
        })) {
          const fromAddr = msg.envelope?.from?.[0] ? `${msg.envelope.from[0].name || ""} <${msg.envelope.from[0].address || ""}>`.trim() : "";
          const toAddr = msg.envelope?.to?.map((t) => `${t.name || ""} <${t.address || ""}>`.trim()).join(", ") || "";
          let hasAttachments = false;
          if (msg.bodyStructure?.childNodes) {
            hasAttachments = msg.bodyStructure.childNodes.some((part) => part.disposition === "attachment" || part.disposition === "inline" && part.parameters?.name);
          }
          messages.unshift({
            uid: msg.uid,
            seq: msg.seq,
            from: fromAddr,
            fromName: msg.envelope?.from?.[0]?.name || msg.envelope?.from?.[0]?.address || "",
            fromEmail: msg.envelope?.from?.[0]?.address || "",
            to: toAddr,
            subject: msg.envelope?.subject || "(Tanpa Subjek)",
            date: msg.envelope?.date,
            flags: Array.from(msg.flags || []),
            isUnread: !msg.flags?.has("\\Seen"),
            isFlagged: msg.flags?.has("\\Flagged"),
            size: msg.size,
            hasAttachments
          });
        }
        let resultList = messages;
        if (search) {
          const q = search.toLowerCase();
          resultList = messages.filter(
            (m) => m.subject.toLowerCase().includes(q) || m.from.toLowerCase().includes(q) || m.fromName.toLowerCase().includes(q)
          );
        }
        res.json({
          success: true,
          folder: rawFolder,
          realFolder: folder,
          total: totalMessages,
          unseen: unseenCount,
          page,
          limit,
          messages: resultList
        });
      } finally {
        lock.release();
      }
    } finally {
      await client.logout();
    }
  } catch (err) {
    console.error("[Webmail Messages Error]:", err.message);
    res.status(400).json({ success: false, error: err.message || "Gagal memuat pesan email." });
  }
}));
app.get("/api/webmail/message/:uid", authenticate, asyncHandler(async (req, res) => {
  try {
    const { uid } = req.params;
    const rawFolder = (req.query.folder || "INBOX").trim();
    const creds = await getUserEmailCredentials(getPool(), req.user, req.query.email);
    if (rawFolder.toLowerCase() === "drafts" || rawFolder.toLowerCase() === "draf") {
      const p = getPool();
      const [rows] = await p.query("SELECT * FROM webmail_drafts WHERE id = ? AND user_email = ? LIMIT 1", [uid, creds.email]);
      if (!rows || rows.length === 0) {
        return res.status(404).json({ error: "Draf tidak ditemukan." });
      }
      const draft = rows[0];
      return res.json({
        success: true,
        uid: Number(draft.id),
        id: Number(draft.id),
        isDraft: true,
        folder: "Drafts",
        from: creds.email,
        fromValue: [{ address: creds.email, name: "Saya" }],
        to: draft.to_recipients || "",
        cc: draft.cc_recipients || "",
        bcc: draft.bcc_recipients || "",
        subject: draft.subject || "(Tanpa Subjek)",
        date: draft.updated_at || draft.created_at,
        html: draft.body_html || "",
        text: draft.body_text || "",
        textAsHtml: draft.body_html || "",
        attachments: []
      });
    }
    const { simpleParser } = await getMailModules();
    if (!simpleParser) {
      return res.status(500).json({ error: "Modul parser email belum tersedia." });
    }
    const client = await createImapClient(creds);
    try {
      const folder = await resolveMailboxName(client, rawFolder);
      const lock = await client.getMailboxLock(folder);
      try {
        const msgData = await client.download(uid, void 0, { uid: true });
        if (!msgData || !msgData.content) {
          return res.status(404).json({ error: "Pesan tidak ditemukan." });
        }
        const parsed = await simpleParser(msgData.content);
        try {
          await client.messageFlagsAdd(uid, ["\\Seen"], { uid: true });
        } catch (e) {
        }
        const attachments = (parsed.attachments || []).map((att, idx) => ({
          id: idx,
          filename: att.filename || `lampiran_${idx + 1}`,
          contentType: att.contentType,
          size: att.size
        }));
        res.json({
          success: true,
          uid: Number(uid),
          folder: rawFolder,
          from: parsed.from?.text || "",
          fromValue: parsed.from?.value || [],
          to: parsed.to ? Array.isArray(parsed.to) ? parsed.to.map((t) => t.text).join(", ") : parsed.to.text : "",
          cc: parsed.cc ? Array.isArray(parsed.cc) ? parsed.cc.map((t) => t.text).join(", ") : parsed.cc.text : "",
          bcc: parsed.bcc ? Array.isArray(parsed.bcc) ? parsed.bcc.map((t) => t.text).join(", ") : parsed.bcc.text : "",
          subject: parsed.subject || "(Tanpa Subjek)",
          date: parsed.date,
          messageId: parsed.messageId,
          inReplyTo: parsed.inReplyTo,
          references: parsed.references,
          html: parsed.html || false,
          text: parsed.text || "",
          textAsHtml: parsed.textAsHtml || "",
          attachments
        });
      } finally {
        lock.release();
      }
    } finally {
      await client.logout();
    }
  } catch (err) {
    console.error("[Webmail Message Detail Error]:", err.message);
    res.status(400).json({ success: false, error: err.message || "Gagal memuat detail pesan." });
  }
}));
